<?php $esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$entry=isset($entry)?$entry:null;$v=function($n,$d='')use($entry){return $entry&&isset($entry->$n)?$entry->$n:$d;};?><!doctype html><html><head><meta charset="utf-8"><?php include('includes/page-title.php'); ?><link href="<?=base_url()?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?=base_url()?>assets/css/app.min.css" rel="stylesheet"></head><body><div id="wrapper"><?php include('includes/top-bar.php');include('includes/sidebar.php');?><div class="content-page"><div class="content"><div class="container-fluid"><div class="card mt-4"><div class="card-body"><a class="btn btn-light float-right" href="<?=base_url()?>Page/opportunity_registry">Back</a><h3><?= $entry?'Edit':'Add';?> Opportunity</h3><p class="text-muted"><?= $esc($sectionName);?></p><form method="post" action="<?=base_url()?>Page/opportunity_registry_save"><input type="hidden" name="id" value="<?= $entry?(int)$entry->id:'';?>"><div class="form-group"><label>Declared Process &amp; Opportunity Statement *</label><textarea class="form-control" rows="4" name="declared_process_opportunity" required><?= $esc($v('declared_process_opportunity'));?></textarea><small class="text-muted">Include the benefit once the opportunity is encountered.</small></div><div class="form-row"><div class="form-group col-md-3"><label>Likelihood</label><select class="form-control rate" id="l" name="likelihood"><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?= (int)$v('likelihood',1)===$i?'selected':'';?>><?=$i?></option><?php endfor;?></select></div><div class="form-group col-md-3"><label>Impact</label><select class="form-control rate" id="i" name="impact"><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?= (int)$v('impact',1)===$i?'selected':'';?>><?=$i?></option><?php endfor;?></select></div><div class="form-group col-md-3"><label>Opportunity Rating</label><input class="form-control" id="r" readonly value="<?= (int)$v('opportunity_rating',1);?>"></div></div><div class="form-row"><div class="form-group col-md-5"><label>Opportunity Pursuit Action Plan</label><textarea class="form-control" rows="3" name="pursuit_action_plan"><?= $esc($v('pursuit_action_plan'));?></textarea></div><div class="form-group col-md-4"><label>Person/Office Responsible</label><input class="form-control" name="person_responsible" value="<?= $esc($v('person_responsible'));?>"></div><div class="form-group col-md-3"><label>Target Date</label><input type="date" class="form-control" name="target_date" value="<?= $esc($v('target_date'));?>"></div></div><button class="btn btn-primary">Save Opportunity</button></form></div></div></div></div><?php include('includes/footer.php');?></div></div><script>function rate(){r.value=l.value*i.value}document.querySelectorAll('.rate').forEach(function(x){x.addEventListener('change',rate)});</script></body></html>
